// Every transaction should have a unique UUID in x-request-id header.
// Body migrated to the current CreateTransactionV5Json schema (account-api spec) using
// transaction_payload_latest.json as the reference template. referenceNumber and
// uniqueIdentifier are generated per request via Postman dynamic variables so reruns
// stay idempotency-safe (Standards #10).
// currencyCode is parametrized via {{currencyCode}}.
// Fee block added per CreateFeeJson schema: applyFee is only used when 'fees' is
// null/empty, so explicitly providing 'fees' here takes precedence over applyFee.
// vat.vatAmount corrected to a Money object (schema: required amount + currencyCode),
// not a bare number.

{
 "transactionTypeCode": "EXT_WITHDRAWAL", // Use the one that is available in environment
 "transactionSubtypeCode": "",
 "valueDate": "{{todayDate}}", // Today's date
 "transactionDTime": "{{$isoTimestamp}}", // dynamic per run
 "money": {
   "amount": 100,
   "currencyCode": "{{currencyCode}}" //
 },
 "details": "Generic debit transaction",
  "referenceNumber": "{{$guid}}", // dynamic per run (Standards #10)
 "source": {
   "sourceName": "CARD_CREDIT",
   "sourceRef": "ID-181279"
 },
  "paymentServiceProviderCode": "TUUM",
  "reversedTransactionId": null,
 "labels": [
   "ACC_VIRTUAL"
 ],
  "uniqueIdentifier": "{{$guid}}", // dynamic per run (Standards #10)
  "applyFee": true,
  "fees": [
    {
      "feeTypeCode": "EXTERNAL2ACC_FEE",
      "details": "Incoming external payment fee",
      "source": {
        "sourceName": "CARD",
        "sourceRef": "{{$guid}}",
        "sourceLink": "https://tuum.com"
      },
      "money": {
        "amount": 5,
        "currencyCode": "{{currencyCode}}"
      },
      "vat": {
        "vatCalculationMethod": "EXCLUSIVE",
        "vatRate": 20.0,
        "vatAmount": {
          "amount": 1.0,
          "currencyCode": "{{currencyCode}}"
        },
        "vatCategory": "STANDARD",
        "vatCode": "STANDARD1",
        "vatTransactionTypeCode": "SALE"
      }
    }
  ]
}

